./runs/20261016T044609488268Z/eligible.jsonl:7:{"item_id":"feed:https://www.engineering.com/?p=151563","kind":"feed","media_url":null,"published_at":"2026-09-30T20:37:29Z","publisher_id":"engineering-com","retrieved_at":"2026-10-16T02:55:38Z","segments_path":null,"source_id":"engineering-com-ai","text_path":"data/assets/feed_https_www.engineering.com_p_151563/90e3adc0a87a45dc20689ae62db7125fe378f8191522f5954fae4ace5e96c803.txt","title":"Welcome to the vibe-CAD era","url":"https://www.engineering.com/welcome-to-the-vibe-cad-era/","version_id":"90e3adc0a87a45dc20689ae62db7125fe378f8191522f5954fae4ace5e96c803"}
./runs/20261016T044609488268Z/eligible.jsonl:9:{"item_id":"podcast:b836fa1b-9246-43d5-8cbb-cf1446760a6d","kind":"podcast","media_url":"https://pscrb.fm/rss/p/dts.podtrac.com/redirect.mp3/media.transistor.fm/217445d3/e1eb0b6a.mp3","published_at":"2026-10-01T09:00:00Z","publisher_id":"changelog-media","retrieved_at":"2026-10-15T20:25:21Z","segments_path":"data/assets/podcast_b836fa1b-9246-43d5-8cbb-cf1446760a6d/a0beee0f49195b6f0b08b75af793b6f6acaf56a159b58771b1c5d8f6c294b282.segments.json","source_id":"practical-ai","text_path":"data/assets/podcast_b836fa1b-9246-43d5-8cbb-cf1446760a6d/a0beee0f49195b6f0b08b75af793b6f6acaf56a159b58771b1c5d8f6c294b282.txt","title":"Open models and the future of Physical AI with NVIDIA","url":"https://pscrb.fm/rss/p/dts.podtrac.com/redirect.mp3/media.transistor.fm/217445d3/e1eb0b6a.mp3","version_id":"a0beee0f49195b6f0b08b75af793b6f6acaf56a159b58771b1c5d8f6c294b282"}
./runs/20261016T153413218193Z/logs/editorial-create_briefs-sh-draft-01-00ade5af501840949a86d221f9797faf-attempt-1.events.jsonl:4:{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"piece_id\":\"01\",\"title\":\"CAD AI Moves Into the Workflow, but the Checks Still Lag\",\"question\":\"What changed, and which developments matter most to this audience?\",\"argument\":\"The meaningful shift is from AI demonstrations toward CAD-adjacent workflow tools: text-generated custom features, visual retrieval of existing models, simulation setup from CAD, and tested drawing-to-CAD conversion. These developments can reduce modeling and handoff work, but they do not yet make generated geometry production-ready by default. The strongest near-term opportunity is supervised first-draft and retrieval work inside native engineering systems, with explicit geometry, tolerance, simulation-input, and manufacturing checks retained.\",\"synthesis\":\"Commercial CAD vendors are productizing AI at the interfaces around geometry—search, reusable FeatureScript tools, and simulation setup—while Engineering.com’s Backflip test supplies a narrower independent check on one geometry-generation workflow. Taken together, the evidence suggests that the practical change is not autonomous engineering: it is a growing set of assisted entry points into existing CAD and simulation environments. The parallel robotics evidence reinforces the same distinction: NVIDIA’s CAD-to-simulation workflow checks asset scale, joints, collision geometry, and grasp behavior in simulation, which is more concrete than visual plausibility but still does not establish physical transfer or manufacturing fitness.\",\"limitations\":\"The most direct independent CAD test covers only two successful, relatively simple speed-modeling drawings and one failed multibody drawing; it cannot establish performance on shop drawings, tolerance-critical parts, or real production workflows. Most other evidence is vendor reporting about released or planned capabilities, so teams need their own representative test sets and release gates.\",\"claims\":[{\"claim_id\":\"01-c1\",\"statement\":\"Engineering.com reported that Backflip’s drawing-to-CAD output matched the reference mass in two tested drawing conversions after STEP import into Fusion and application of 1060 aluminum.\",\"type\":\"reported_fact\",\"evidence\":[{\"item_id\":\"feed:https://www.engineering.com/?p=151563\",\"version_id\":\"90e3adc0a87a45dc20689ae62db7125fe378f8191522f5954fae4ace5e96c803\",\"locator\":{\"type\":\"text\",\"quote\":\"I can verify that Backflip got it exactly correct.\"}}]},{\"claim_id\":\"01-c2\",\"statement\":\"The same Engineering.com test found Backflip created only one of seven bodies for a multibody wire-shelf drawing.\",\"type\":\"reported_fact\",\"evidence\":[{\"item_id\":\"feed:https://www.engineering.com/?p=151563\",\"version_id\":\"90e3adc0a87a45dc20689ae62db7125fe378f8191522f5954fae4ace5e96c803\",\"locator\":{\"type\":\"text\",\"quote\":\"it only created one of the seven bodies\"}}]},{\"claim_id\":\"01-c3\",\"statement\":\"Onshape says its FeatureScript MCP Server lets engineers use natural-language requests to have AI create, test, debug, and refine custom CAD functionality.\",\"type\":\"source_claim\",\"evidence\":[{\"item_id\":\"feed:https://www.onshape.com/en/blog/featurescript-mcp-server-use-cases-text-code-cad\",\"version_id\":\"9656a0a35f95ac0e0adb6ba1530e2759342633cbcecba8de9948699a032ab5a8\",\"locator\":{\"type\":\"text\",\"quote\":\"create, test, debug, and refine custom CAD functionality\"}}]},{\"claim_id\":\"01-c4\",\"statement\":\"Onshape says its opt-in AI Descriptive Image Search generates searchable descriptions from model thumbnails and currently applies only to public documents.\",\"type\":\"source_claim\",\"evidence\":[{\"item_id\":\"feed:https://www.onshape.com/en/blog/ai-generated-thumbnail-description-search\",\"version_id\":\"b2755a997c3cdda71421bbdd40ee9721d353cbc20ed2f1f80e91169757b9bbd2\",\"locator\":{\"type\":\"text\",\"quote\":\"generates searchable descriptions from model thumbnails\"}},{\"item_id\":\"feed:https://www.onshape.com/en/blog/ai-generated-thumbnail-description-search\",\"version_id\":\"b2755a997c3cdda71421bbdd40ee9721d353cbc20ed2f1f80e91169757b9bbd2\",\"locator\":{\"type\":\"text\",\"quote\":\"public documents only\"}}]},{\"claim_id\":\"01-c5\",\"statement\":\"SimScale says its Onshape agent can propose a setup, mesh and run physics from a CAD model, then report results back in Onshape.\",\"type\":\"source_claim\",\"evidence\":[{\"item_id\":\"feed:https://www.engineering.com/?p=151329\",\"version_id\":\"a5a6e64fd4f2a87b5b45be5afd0c01d19fd3ee1e8b8f12be9e7e49964e03d82b\",\"locator\":{\"type\":\"text\",\"quote\":\"propose an appropriate setup, mesh and run the physics\"}}]},{\"claim_id\":\"01-c6\",\"statement\":\"The MIT-CDFG survey concludes that current frontier-model outputs are reliable enough for first drafts but do not yet demonstrate engineering requirements such as tolerances or manufacturability.\",\"type\":\"source_claim\",\"evidence\":[{\"item_id\":\"feed:https://mit-cdfg.github.io/Survey-AI-for-3D-modeling-Robotics/#view-stats\",\"version_id\":\"08b1c2cdebb5796d7332d57e8928784a621aec9f82db91448016eaa53ea51fe5\",\"locator\":{\"type\":\"text\",\"quote\":\"reliable enough to serve as first drafts\"}},{\"item_id\":\"feed:https://mit-cdfg.github.io/Survey-AI-for-3D-modeling-Robotics/#view-stats\",\"version_id\":\"08b1c2cdebb5796d7332d57e8928784a621aec9f82db91448016eaa53ea51fe5\",\"locator\":{\"type\":\"text\",\"quote\":\"tolerances, manufacturability or safe unsupervised operation\"}}]},{\"claim_id\":\"01-c7\",\"statement\":\"NVIDIA describes a CAD-to-simulation workflow that checks imported robot scale, parts, appearance, joints, collision geometry, physical properties, and a simulated grasp before a full Isaac Sim sequence.\",\"type\":\"source_claim\",\"evidence\":[{\"item_id\":\"youtube:H5UaOdIZERw\",\"version_id\":\"c86fae4c3874c6aa997843fe5a3365bf0a32d21acb0927fbcea32b10e0709a06\",\"locator\":{\"type\":\"segment\",\"segment_id\":\"s0004\"}},{\"item_id\":\"youtube:H5UaOdIZERw\",\"version_id\":\"c86fae4c3874c6aa997843fe5a3365bf0a32d21acb0927fbcea32b10e0709a06\",\"locator\":{\"type\":\"segment\",\"segment_id\":\"s0006\"}}]},{\"claim_id\":\"01-c8\",\"statement\":\"The podcast reports that five general models left 63 of 84 robot tasks unsolved, underscoring that executable task checks reveal limits that broad capability framing can obscure.\",\"type\":\"inference\",\"evidence\":[{\"item_id\":\"podcast:https://physicalaipodcast.co/episodes/010\",\"version_id\":\"85cb287a2441351d8480acecc45d2ae3d6c8d1e3d180eee941a34d7bcda762d1\",\"locator\":{\"type\":\"segment\",\"segment_id\":\"s0005\"}},{\"item_id\":\"feed:https://mit-cdfg.github.io/Survey-AI-for-3D-modeling-Robotics/#view-stats\",\"version_id\":\"08b1c2cdebb5796d7332d57e8928784a621aec9f82db91448016eaa53ea51fe5\",\"locator\":{\"type\":\"text\",\"quote\":\"what this advance means in practice\"}}]}]}"}}
